-- nightly cleanup: delete customers who have never placed an order
-- orders.customer_id is nullable (guest checkouts store NULL)
BEGIN;

DELETE FROM customers
WHERE id NOT IN (
    SELECT customer_id
    FROM orders
);

COMMIT;

