def withdraw(conn, account_id: int, cents: int) -> None:
    with conn.transaction():
        row = conn.execute(
            "SELECT balance_cents FROM accounts WHERE id = %s", (account_id,)
        ).fetchone()
        if row["balance_cents"] < cents:
            raise InsufficientFunds()
        conn.execute(
            "UPDATE accounts SET balance_cents = %s WHERE id = %s",
            (row["balance_cents"] - cents, account_id),
        )

fixedCode:
def withdraw(conn, account_id: int, cents: int) -> None:
    with conn.transaction():
        row = conn.execute(
            "SELECT balance_cents FROM accounts WHERE id = %s FOR UPDATE", (account_id,)
        ).fetchone()
        if row["balance_cents"] < cents:
            raise InsufficientFunds()
        conn.execute(
            "UPDATE accounts SET balance_cents = balance_cents - %s WHERE id = %s",
            (cents, account_id),
        )

